Method.Source:
/// <summary>
/// Event button to click
/// </summary>
/// <param name="sender">
/// Controlbutton
/// </param>
/// <param name="e">
/// FormControlEventArgs
/// </param>
[FormControlEventHandler(formControlStr(WHSCloseContainerProfile, AVAPrinterSetupButton), FormControlEventType::Clicked)]
public static void AVAPrinterSetupButton_OnClicked(FormControl sender, FormControlEventArgs e)
{
    WHSCloseContainerProfile    closeContainerProfile;
    FormRun                     element =  sender.formRun();
    FormDataSource              whsCloseContainerProfile_ds  = element.dataSource();

    closeContainerProfile= whsCloseContainerProfile_ds.cursor();

    closeContainerProfile.avaSetupPrinter();

    sender.hasChanged(true);
}
